<script setup>
import { useForm } from '@inertiajs/vue3'; import { ref } from 'vue'; import AppLayout from '../../../Layouts/AppLayout.vue';
const props=defineProps({centers:Array,endpoints:Object}); const editing=ref(null); const form=useForm({code:'',name:'',description:'',is_active:true});
const create=()=>{editing.value=null;form.reset();form.is_active=true;}; const edit=center=>{editing.value=center;form.code=center.code;form.name=center.name;form.description=center.description||'';form.is_active=center.is_active;};
const submit=()=>editing.value?form.put(props.endpoints.update.replace('__CENTER__',editing.value.id),{preserveScroll:true,onSuccess:create}):form.post(props.endpoints.store,{preserveScroll:true,onSuccess:create});
</script>
<template><AppLayout title="Centros de costo" eyebrow="Contabilidad analítica" description="Segmenta los movimientos sin modificar el catálogo de cuentas."><div class="grid gap-4 xl:grid-cols-[1fr_380px]"><section class="card overflow-hidden"><div class="table-wrap"><table class="w-full"><thead><tr><th class="table-cell">Código</th><th class="table-cell">Centro</th><th class="table-cell">Movimientos</th><th class="table-cell">Estado</th><th></th></tr></thead><tbody><tr v-for="center in centers" :key="center.id"><td class="table-cell font-mono">{{center.code}}</td><td class="table-cell"><strong>{{center.name}}</strong><small class="block text-slate-400">{{center.description}}</small></td><td class="table-cell">{{center.lines_count}}</td><td class="table-cell">{{center.is_active?'Activo':'Inactivo'}}</td><td class="table-cell text-right"><button class="text-blue-700" @click="edit(center)">Editar</button></td></tr></tbody></table></div><p v-if="!centers.length" class="empty-state">Crea el primer centro para clasificar gastos e ingresos por área.</p></section><form class="card h-fit p-5" @submit.prevent="submit"><h2 class="font-bold">{{editing?'Editar centro':'Nuevo centro de costo'}}</h2><label class="field-label mt-4 block">Código<input v-model="form.code" class="control" required></label><label class="field-label mt-3 block">Nombre<input v-model="form.name" class="control" required></label><label class="field-label mt-3 block">Descripción<textarea v-model="form.description" class="control"></textarea></label><label class="mt-3 flex items-center gap-2 text-sm"><input v-model="form.is_active" type="checkbox"> Centro activo</label><p v-if="Object.keys(form.errors).length" class="mt-3 text-xs text-rose-600">{{Object.values(form.errors).join(' · ')}}</p><div class="mt-4 flex gap-2"><button class="btn-primary" :disabled="form.processing">Guardar</button><button v-if="editing" type="button" class="btn-soft" @click="create">Cancelar</button></div></form></div></AppLayout></template>
